(143970, 7210, 472, '<td valign="top">perty. nice composition.  focus could be crisper or maybe a touch of sharpening filter. mag99</td>', 'perty. nice composition.  focus could be crisper or maybe a touch of sharpening filter. mag99', '2002-10-27 01:40:00.000000', NULL, 1),
(143971, 7211, 4625, '<td valign="top">Spooky.</td>', 'Spooky.', '2002-10-21 02:19:00.000000', NULL, 1),
(143972, 7211, 4564, '<td valign="top">funny. on par with theme. uninspiring to me. 5</td>', 'funny. on par with theme. uninspiring to me. 5', '2002-10-21 16:08:00.000000', NULL, 1),
