(145185, 7326, 2866, '<td valign="top">Hot.</td>', 'Hot.', '2002-10-22 20:22:00.000000', NULL, 1),
(145186, 7326, 3317, '<td valign="top">the best photos of this challenge use the single light source to create a war between light and shadow. this lady''s lovely, but sweet legs ain''t always enough, three.</td>', 'the best photos of this challenge use the single light source to create a war between light and shadow. this lady''s lovely, but sweet legs ain''t always enough, three.', '2002-10-23 15:34:00.000000', NULL, 1),
(145187, 7326, 2716, '<td valign="top">Looks like to much light to me, but I''ll give you an 8 beacuse she''s sweet.  I would''ve liked the shot a bit more if you wouldn''t have cut off a part of her head.</td>', 'Looks like to much light to me, but I''ll give you an 8 beacuse she''s sweet.  I would''ve liked the shot a bit more if you wouldn''t have cut off a part of her head.', '2002-10-23 20:06:00.000000', NULL, 1),
