(145190, 7326, 3900, '<td valign="top">Ummm, this makes me horny. Was that your intention?</td>', 'Ummm, this makes me horny. Was that your intention?', '2002-10-25 06:16:00.000000', NULL, 1),
(145191, 7326, 843, '<td valign="top">Would have liked the whole head in the frame, but a nice image.</td>', 'Would have liked the whole head in the frame, but a nice image.', '2002-10-25 10:03:00.000000', NULL, 1),
