INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(147040, 7463, 4173, '<td valign="top">Colorful and bright, even though there is only one light source.  Great setup and even better lighting.  Wonderful vibrant interesting submission.</td>', 'Colorful and bright, even though there is only one light source.  Great setup and even better lighting.  Wonderful vibrant interesting submission.', '2002-10-27 23:59:00.000000', NULL, 1),
(147041, 7464, 3080, '<td valign="top">The lighting coming out of the 2 jack-o-lanterns on the left is a bit harsh.  especially on the far left one in the mouth/nose area.  The colors are great though, and the angle and framing/cropping are also good.  focus and clarity are great.  love their faces. nice shot. Good luck in the challenge. ~Hbunch7187~</td>', 'The lighting coming out of the 2 jack-o-lanterns on the left is a bit harsh.  especially on the far left one in the mouth/nose area.  The colors are great though, and the angle and framing/cropping are also good.  focus and clarity are great.  love their faces. nice shot. Good luck in the challenge. ~Hbunch7187~', '2002-10-21 03:51:00.000000', NULL, 1),
(147042, 7464, 1073, '<td valign="top">One light source?</td>', 'One light source?', '2002-10-21 06:28:00.000000', NULL, 1),
(147043, 7464, 4297, '<td valign="top">great idea for the time of year.. Not the most inspiring of photos but enjoyable to look at... 6</td>', 'great idea for the time of year.. Not the most inspiring of photos but enjoyable to look at... 6', '2002-10-21 09:54:00.000000', NULL, 1),
(147044, 7464, 2567, '<td valign="top">Had marked this one as a 10 but then remembered a single light source.  8</td>', 'Had marked this one as a 10 but then remembered a single light source.  8', '2002-10-21 12:04:00.000000', NULL, 1),
(147045, 7464, 3323, '<td valign="top">single artifical light source.</td>', 'single artifical light source.', '2002-10-21 17:17:00.000000', NULL, 1),
